<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useAuth } from '~/composables/useAuth'
import { useApiClient } from '~/utils/api'
const emit = defineEmits<{ 'toggle-sidebar': [] }>(); const api=useApiClient(); const { currentUser, logout }=useAuth(); const search=ref(''); const notifications=ref<any[]>([]); const notificationOpen=ref(false); const themeOpen=ref(false); const languageOpen=ref(false); const userOpen=ref(false); const dark=ref(false)
const unreadCount=computed(()=>notifications.value.filter(n=>!n.is_read).length); const roleLabel=computed(()=>({admin:'অ্যাডমিন',super_admin:'সুপার অ্যাডমিন',teacher:'শিক্ষক',student:'শিক্ষার্থী',guardian:'অভিভাবক'} as any)[currentUser.value?.role]||'ব্যবহারকারী')
onMounted(async()=>{dark.value=localStorage.getItem('rihal_theme')==='dark'; applyTheme(); try{const r=await api.get('/notifications?per_page=8'); notifications.value=r.data?.data?.data||r.data?.data||[]}catch{}})
function setTheme(value:string){dark.value=value==='dark'; localStorage.setItem('rihal_theme',value); applyTheme(); themeOpen.value=false} function applyTheme(){if(import.meta.client) document.documentElement.dataset.theme=dark.value?'dark':'light'} function searchStudents(){if(search.value.trim()) navigateTo(`/students?search=${encodeURIComponent(search.value.trim())}`)}
</script>

